const entrada = $input.first().json;
const fail = (motivo) => [{json:{situacao:'REVISAO', resumo:'Entrada precisa de revisão: '+motivo, selecionados:[], motivo}}];
function dia(valor) {
  if (typeof valor !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(valor)) return null;
  const data = new Date(valor+'T00:00:00Z');
  return Number.isFinite(data.getTime()) && data.toISOString().slice(0,10) === valor ? data.getTime() : null;
}
const inicio = dia(entrada.data_referencia);
const dias = Number(entrada.dias);
if (inicio === null || !Number.isInteger(dias) || dias < 1 || dias > 31) return fail('período inválido');
let registros;
try { registros = JSON.parse(entrada.dados); } catch { return fail('lista JSON inválida'); }
if (!Array.isArray(registros)) return fail('dados não são uma lista');
const ids = new Set();
for (const r of registros) {
  if (!r || typeof r.id !== 'string' || !r.id.trim() || typeof r.titulo !== 'string' || !r.titulo.trim() || dia(r.prazo) === null || !['aberta','concluida'].includes(r.estado)) return fail('registro incompleto ou inválido: '+(r?.id || 'sem id'));
  if (ids.has(r.id)) return fail('identificador duplicado: '+r.id);
  ids.add(r.id);
}
const fim = inicio + dias * 86400000;
const selecionados = registros.filter(r => r.estado === 'aberta' && dia(r.prazo) >= inicio && dia(r.prazo) < fim)
  .sort((a,b) => a.prazo.localeCompare(b.prazo) || a.id.localeCompare(b.id));
const resumo = selecionados.length ? selecionados.map(r => r.id+' | '+r.prazo+' | '+r.titulo).join('\n') : 'Nenhuma pendência no período.';
return [{json:{situacao:selecionados.length ? 'OK' : 'VAZIO', resumo, selecionados, quantidade:selecionados.length}}];
